import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Statistics-Positions-and-Labels.md","filePath":"manual-zh/CTABLES-Statistics-Positions-and-Labels.md","lastUpdated":1785684581000}'),o={name:"manual-zh/CTABLES-Statistics-Positions-and-Labels.md"};function n(h,t,s,c,i,S){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h4 id="_15-7-3-统计量的位置与标签" tabindex="-1">15.7.3 统计量的位置与标签 <a class="header-anchor" href="#_15-7-3-统计量的位置与标签" aria-label="Permalink to &quot;15.7.3 统计量的位置与标签&quot;">​</a></h4><pre><code>/SLABELS
    [POSITION={COLUMN _|_ ROW _|_ LAYER}]
    [VISIBLE={YES _|_ NO}]
</code></pre><p><code>SLABELS</code> 子命令用于控制其前面的 <code>TABLE</code> 子命令中汇总统计量的位置与可见性。</p><p><code>POSITION</code> 设置汇总统计量所出现的轴。默认使用 <code>POSITION=COLUMN</code>，此时每个汇总统计量显示为一列。例如：</p><pre><code>CTABLES /TABLE=age [MEAN, MEDIAN] BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th>Mean</th><th>Median</th><th>Mean</th><th>Median</th></tr></thead><tbody><tr><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>D1. AGE: What is your age?</td><td>46</td><td>45</td><td>50</td><td>52</td></tr></tbody></table><p>使用 <code>POSITION=ROW</code> 时，每个汇总统计量显示为一行，如下所示：</p><pre><code>CTABLES /TABLE=age [MEAN, MEDIAN] BY gender /SLABELS POSITION=ROW.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td>D1. AGE: What is your age?</td><td>Mean</td><td>46</td><td>50</td></tr><tr><td>Median</td><td>45</td><td>52</td><td></td></tr></tbody></table><p><code>POSITION=LAYER</code> 也可用，可将每个汇总统计量放置在一个独立的层中。</p><p>汇总统计量的标签默认显示。使用 <code>VISIBLE=NO</code> 可将其隐藏。由于未加标签的数据容易造成混淆，只有在数据的含义显而易见时才应考虑这样做，如下面这个简单示例所示：</p><pre><code>CTABLES /TABLE=ageGroup [TABLEPCT] /SLABELS VISIBLE=NO.
</code></pre><table tabindex="0"><thead><tr><th>Age group</th><th>15 or younger</th><th>.0%</th></tr></thead><tbody><tr><td>16 to 25</td><td>15.7%</td><td></td></tr><tr><td>26 to 35</td><td>13.8%</td><td></td></tr><tr><td>36 to 45</td><td>14.8%</td><td></td></tr><tr><td>46 to 55</td><td>16.8%</td><td></td></tr><tr><td>56 to 65</td><td>17.8%</td><td></td></tr><tr><td>66 or older</td><td>21.1%</td><td></td></tr></tbody></table>`,13)])])}const p=d(o,[["render",n]]);export{l as __pageData,p as default};
